ROOT = Path(__file__).resolve().parent
FOUNDATION = ROOT / "alliance_property_brain_foundation_v1.py"
GOLD_V2 = ROOT / "alliance_property_brain_gold_v2.py"
OPTIONAL = ROOT / "alliance_optional_property_modules.py"
